(function(E){ const x = E["exam-07"] = E["exam-07"] || {units:{}}; (x.units = x.units || {})["x07-l1"] = {"id":"x07-l1","patterns":["L1-home","PARA-money","PARA-time"],"title":{"en":"Listening Part 1: hiring for a new home","tr":"Listening Part 1: yeni ev için kiralama","fa":"Listening Part 1: کرایه برای خانه‌ی تازه"},"objective":{"en":"In this lesson you will learn to complete notes during a phone call to a hire company: choose the right price, write what is available now, keep printed words out of your answer and spell a name correctly.","tr":"Bu derste bir kiralama şirketine yapılan telefon görüşmesi sırasında notları doldurmayı öğreneceksin: doğru fiyatı seçecek, şu an mevcut olanı yazacak, yazılı kelimeleri cevabına katmayacak ve bir ismi doğru yazacaksın.","fa":"در این درس یاد می‌گیری در طول تماس تلفنی با یک شرکت کرایه، یادداشت‌ها را کامل کنی: قیمت درست را انتخاب کنی، چیزی را که الان موجود است بنویسی، کلمه‌های چاپ‌شده را در جوابت تکرار نکنی و یک اسم را درست بنویسی."},"sessions":[["explain"],["drill"],["exit"]],"explain":{"title":{"en":"Listening Part 1: hiring for a new home","tr":"Listening Part 1: yeni ev için kiralama","fa":"Listening Part 1: کرایه برای خانه‌ی تازه"},"objective":{"en":"In this lesson you will learn to complete notes during a phone call to a hire company: choose the right price, write what is available now, keep printed words out of your answer and spell a name correctly.","tr":"Bu derste bir kiralama şirketine yapılan telefon görüşmesi sırasında notları doldurmayı öğreneceksin: doğru fiyatı seçecek, şu an mevcut olanı yazacak, yazılı kelimeleri cevabına katmayacak ve bir ismi doğru yazacaksın.","fa":"در این درس یاد می‌گیری در طول تماس تلفنی با یک شرکت کرایه، یادداشت‌ها را کامل کنی: قیمت درست را انتخاب کنی، چیزی را که الان موجود است بنویسی، کلمه‌های چاپ‌شده را در جوابت تکرار نکنی و یک اسم را درست بنویسی."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"10"},{"label":{"en":"Speakers","tr":"Konuşan","fa":"گوینده"},"value":"2"},{"label":{"en":"Word limit","tr":"Kelime sınırı","fa":"سقف کلمه"},"value":{"en":"1 word / number","tr":"1 kelime / sayı","fa":"۱ کلمه / عدد"}}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: kitchen equipment for a rented flat","tr":"Bu sınav: kiralık bir daire için mutfak eşyası","fa":"این آزمون: وسایل آشپزخانه برای یک آپارتمان اجاره‌ای"},"intro":{"en":"Part 1 is always an everyday call or conversation. Home services, moving and renting are a regular situation. The assistant usually goes through each item in turn and then gives general information.","tr":"Part 1 her zaman günlük bir telefon ya da konuşmadır. Ev hizmetleri, taşınma ve kiralama düzenli çıkan bir durumdur. Görevli genelde her eşyayı sırayla anlatır, sonra genel bilgi verir.","fa":"Part 1 همیشه یک تماس یا گفتگوی روزمره است. خدمات خانه، اسباب‌کشی و اجاره موقعیتی همیشگی است. کارمند معمولاً هر وسیله را به نوبت توضیح می‌دهد و بعد اطلاعات کلی می‌دهد."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x07-l1-ctx","exam":true,"patterns":["L1-home","PARA-money","PARA-time"],"often":{"pattern":"L1-home","n":7,"of":40,"label":{"en":"Comes up often in the real exam: 7 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 7’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۷ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Hiring things for a new home","tr":"Yeni bir ev için eşya kiralamak","fa":"کرایه کردن وسایل برای خانه‌ی تازه"},"asks":{"en":"A tenant phones a company to hire kitchen equipment. The notes cover each item (price, colour, what is included), then delivery, insurance, the contract and what to show on the day.","tr":"Bir kiracı mutfak eşyası kiralamak için bir şirketi arıyor. Notlar her eşyayı (fiyat, renk, neyin dahil olduğu), sonra teslimatı, sigortayı, sözleşmeyi ve teslim günü neyin gösterileceğini kapsıyor.","fa":"یک مستأجر به شرکتی زنگ می‌زند تا وسایل آشپزخانه کرایه کند. یادداشت‌ها هر وسیله (قیمت، رنگ، چه چیزی شامل است) و بعد تحویل، بیمه، قرارداد و چیزی را که روز تحویل باید نشان بدهی پوشش می‌دهند."},"fields":["Item","Monthly price","Colour","Included","Delivery day","Delivery charge","Insurance","Contract","Name","Identification"],"words":[{"a":"per month","b":"a month / monthly","tr":"aylık","fa":"ماهانه"},{"a":"contract","b":"an agreement for a fixed time","tr":"sözleşme","fa":"قرارداد"},{"a":"comes down to","b":"is reduced to / is cheaper at","tr":"... düşer","fa":"کم می‌شود به"},{"a":"out of stock","b":"we’ve run out of / none left","tr":"stokta yok","fa":"موجود نیست"},{"a":"includes","b":"is part of the price / at no extra cost","tr":"dahildir","fa":"شاملِ ... است"},{"a":"installation","b":"connecting it / setting it up","tr":"kurulum","fa":"نصب"},{"a":"fully booked","b":"no slots left","tr":"tamamen dolu","fa":"کاملاً پر"},{"a":"altogether","b":"in total / for both","tr":"toplamda","fa":"روی‌هم‌رفته"},{"a":"minimum","b":"at least / the shortest possible","tr":"en az","fa":"حداقل"},{"a":"identification","b":"ID / proof of who you are","tr":"kimlik","fa":"مدرک شناسایی"},{"a":"automatically","b":"without you doing anything","tr":"otomatik olarak","fa":"خودکار"}],"traps":[{"en":"Two prices: a full price and a contract price, or a price per item and a price for two. The words next to the gap tell you which one.","tr":"İki fiyat: tam fiyat ve sözleşme fiyatı ya da tek ürün fiyatı ve iki ürün fiyatı. Boşluğun yanındaki kelimeler hangisi olduğunu söyler.","fa":"دو قیمت: قیمت کامل و قیمت قراردادی، یا قیمت هر وسیله و قیمت برای دو وسیله. کلمه‌های کنار جای خالی می‌گویند کدام."},{"en":"An option that is not available: \"We normally have... but we’ve run out.\" Write what is possible now.","tr":"Mevcut olmayan bir seçenek: \"Normalde ... var ama tükendi.\" Şu an mümkün olanı yaz.","fa":"گزینه‌ای که در دسترس نیست: «معمولاً ... داریم، اما تمام شده». چیزی را بنویس که الان ممکن است."},{"en":"What most people do is not always accepted: \"A lot of people show X, but that isn’t enough.\"","tr":"Çoğu insanın yaptığı her zaman kabul edilmez: \"Birçok kişi X gösteriyor ama bu yeterli değil.\"","fa":"کاری که بیشتر آدم‌ها می‌کنند همیشه پذیرفته نیست: «خیلی‌ها X نشان می‌دهند، اما کافی نیست»."}],"example":{"lines":[["Assistant","The table is ninety pounds to buy. If you hire it, it’s twelve a month, or ten if you sign up for a year."],["Caller","I’ll take the year."]],"item":"Table hire (12-month contract): £___ a month","answer":"10","why":{"en":"Ninety is the price to buy; twelve is without a contract. The yearly price is 10.","tr":"Doksan satın alma fiyatı; on iki sözleşmesiz fiyat. Yıllık fiyat 10.","fa":"نود قیمت خرید است؛ دوازده بدون قرارداد است. قیمت سالانه ۱۰ است."}}},{"id":"L1-home","ctx":["L1-home"],"title":{"en":"A service for the home or daily life","tr":"Ev ya da günlük yaşam için bir hizmet","fa":"یک خدمت برای خانه یا زندگی روزمره"},"asks":{"en":"A caller arranges a service such as cleaning, furniture hire, photo copying or a library card, or a friend gives advice on local shops, restaurants or moving house. The notes collect the service, the price, the timing and the conditions.","tr":"Arayan temizlik, mobilya kiralama, fotoğraf aktarma ya da kütüphane kartı gibi bir hizmet ayarlar; ya da bir arkadaş yerel dükkânlar, restoranlar ya da taşınma hakkında tavsiye verir. Notlar hizmeti, fiyatı, zamanı ve koşulları toplar.","fa":"تماس‌گیرنده خدمتی مثل نظافت، اجاره‌ی مبلمان، تبدیل عکس یا کارت کتابخانه را هماهنگ می‌کند، یا دوستی درباره‌ی مغازه‌های محل، رستوران‌ها یا اسباب‌کشی توصیه می‌دهد. یادداشت‌ها خدمت، قیمت، زمان و شرایط را جمع می‌کنند."},"fields":["Service / company name","Address","Number of rooms","Day and time of visit","Price / monthly charge","Delivery","Conditions / insurance","Special requests"],"words":[{"a":"delivery","b":"we bring it to your door","tr":"teslimat","fa":"تحویل"},{"a":"monthly","b":"each month / a month","tr":"aylık","fa":"ماهانه"},{"a":"insurance","b":"cover in case something breaks","tr":"sigorta","fa":"بیمه"},{"a":"contract","b":"you sign up for six months","tr":"sözleşme","fa":"قرارداد"},{"a":"free of charge","b":"at no extra cost / we don't charge for","tr":"ücretsiz","fa":"رایگان"},{"a":"quote","b":"a price we give you first","tr":"fiyat teklifi","fa":"برآورد قیمت"},{"a":"damage","b":"if anything gets broken","tr":"hasar","fa":"خسارت"},{"a":"appointment","b":"we'll book you in for","tr":"randevu","fa":"وقت قبلی"},{"a":"recommend","b":"you should try / the best one is","tr":"tavsiye etmek","fa":"پیشنهاد کردن"},{"a":"nearby","b":"just round the corner","tr":"yakında","fa":"همین نزدیکی"},{"a":"vegetarian","b":"no meat dishes","tr":"vejetaryen","fa":"گیاهی"},{"a":"every other week","b":"once a fortnight","tr":"iki haftada bir","fa":"دو هفته یک بار"}],"traps":[{"en":"The price has parts: a monthly charge plus a one-off delivery fee. Read the heading to know which part it wants.","tr":"Fiyatın parçaları vardır: aylık ücret artı tek seferlik teslimat ücreti. Hangi parçanın istendiğini başlıktan anla.","fa":"قیمت چند بخش دارد: هزینه‌ی ماهانه به‌اضافه‌ی هزینه‌ی یک‌باره‌ی تحویل. از روی عنوان بفهم کدام بخش را می‌خواهد."},{"en":"Offers change the number: \"normally £30, but this month it’s £25\".","tr":"Kampanyalar sayıyı değiştirir: \"normalde 30 pound ama bu ay 25\".","fa":"تخفیف‌ها عدد را عوض می‌کنند: «معمولاً ۳۰ پوند است، ولی این ماه ۲۵»."},{"en":"Street and company names are spelled letter by letter. Write every letter.","tr":"Sokak ve şirket adları harf harf söylenir. Her harfi yaz.","fa":"اسم خیابان و شرکت حرف به حرف هجی می‌شود. همه‌ی حرف‌ها را بنویس."}],"example":{"lines":[["Agent","A cleaner costs fifteen pounds an hour."],["Caller","How many hours for a two-bedroom flat?"],["Agent","Normally three, but the first visit takes four, because we clean the windows too."]],"item":"First visit: ___ hours","answer":"4","why":{"en":"Three is the normal visit. The heading asks about the first visit, which takes four.","tr":"Üç saat normal ziyaret. Başlık ilk ziyareti soruyor; o dört saat sürüyor.","fa":"سه ساعت برای ویزیت معمولی است. عنوان درباره‌ی اولین ویزیت می‌پرسد که چهار ساعت طول می‌کشد."}},"general":true,"patterns":["L1-home"],"often":{"pattern":"L1-home","n":7,"of":40,"label":{"en":"Comes up often in the real exam: 7 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 7’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۷ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Ten notes, one break","tr":"On not, bir ara","fa":"ده یادداشت، یک وقفه"},"body":{"en":"Questions 1-10 are notes under a few headings. You read Questions 1-6 first and Questions 7-10 in the break. The answers come in order. Limit: ONE WORD AND/OR A NUMBER, so prices are written as figures.","tr":"Soru 1-10 birkaç başlık altındaki notlardır. Önce Soru 1-6’yı, molada Soru 7-10’u okursun. Cevaplar sırayla gelir. Sınır: ONE WORD AND/OR A NUMBER; fiyatlar rakamla yazılır.","fa":"سؤال‌های ۱ تا ۱۰ یادداشت‌هایی زیر چند عنوان‌اند. اول سؤال‌های ۱ تا ۶ را می‌خوانی و در وقفه ۷ تا ۱۰ را. جواب‌ها به ترتیب می‌آیند. سقف: ONE WORD AND/OR A NUMBER؛ قیمت‌ها با رقم نوشته می‌شوند."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Four steps","tr":"Dört adım","fa":"چهار قدم"},"steps":[{"en":"Read the words around each gap: \"a month\", \"on a 12-month contract\", \"per item\" tell you which price.","tr":"Her boşluğun etrafındaki kelimeleri oku: \"a month\", \"on a 12-month contract\", \"per item\" hangi fiyat olduğunu söyler.","fa":"کلمه‌های دور هر جای خالی را بخوان: «a month»، «on a 12-month contract»، «per item» می‌گویند کدام قیمت."},{"en":"Listen for \"actually\", \"I’m sorry\" and \"run out\": the first option may not be available.","tr":"\"Actually\", \"I’m sorry\" ve \"run out\" ifadelerine kulak ver: ilk seçenek mevcut olmayabilir.","fa":"به «actually»، «I’m sorry» و «run out» گوش بده: ممکن است گزینه‌ی اول موجود نباشد."},{"en":"Do not repeat a word that is printed next to the gap.","tr":"Boşluğun yanında yazılı bir kelimeyi tekrarlama.","fa":"کلمه‌ای را که کنار جای خالی چاپ شده تکرار نکن."},{"en":"Write a spelled name letter by letter, and check it at the end.","tr":"Harf harf söylenen bir ismi harf harf yaz ve sonunda kontrol et.","fa":"اسمی را که هجی می‌شود حرف به حرف بنویس و آخر کار چکش کن."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"The usual thing is not always the answer","tr":"Olağan olan her zaman cevap değildir","fa":"چیز معمول همیشه جواب نیست"},"body":{"en":"Assistants often mention what normally happens or what most customers do, and then say that it does not apply here: an item that is out of stock, a slot that is booked, a document that is not accepted. Write what applies to this caller.","tr":"Görevliler çoğu zaman normalde ne olduğunu ya da çoğu müşterinin ne yaptığını söyler, sonra bunun burada geçerli olmadığını belirtir: stokta olmayan bir ürün, dolu bir saat, kabul edilmeyen bir belge. Bu arayan kişi için geçerli olanı yaz.","fa":"کارمندها اغلب می‌گویند معمولاً چه اتفاقی می‌افتد یا بیشتر مشتری‌ها چه می‌کنند و بعد می‌گویند این‌جا صدق نمی‌کند: وسیله‌ای که موجود نیست، وقتی که پر است، مدرکی که پذیرفته نمی‌شود. چیزی را بنویس که برای همین تماس‌گیرنده صدق می‌کند."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One gap, step by step","tr":"Bir boşluk, adım adım","fa":"یک جای خالی، قدم به قدم"},"instruction":"Complete the notes below. Write ONE WORD AND/OR A NUMBER for each answer.","item":"Sofa · available in ___ only","lines":[["Assistant","It usually comes in blue or grey. Let me check... no, the blue ones have all gone, so it’s grey only this month."]],"answer":"grey","walk":[{"en":"Before you listen: the gap needs a colour, and \"only\" tells you there is just one.","tr":"Dinlemeden önce: boşluk bir renk istiyor ve \"only\" tek bir renk olduğunu söylüyor.","fa":"قبل از گوش دادن: جای خالی یک رنگ می‌خواهد و «only» می‌گوید فقط یکی هست."},{"en":"You hear two colours, then \"the blue ones have all gone\".","tr":"İki renk duyuyorsun, sonra \"mavilerin hepsi bitti\".","fa":"دو رنگ می‌شنوی و بعد «آبی‌ها همه تمام شده‌اند»."},{"en":"Write grey. \"only\" is printed, so one word is enough.","tr":"grey yaz. \"only\" yazılı, tek kelime yeter.","fa":"grey را بنویس. «only» چاپ شده، پس یک کلمه کافی است."}]},"quick":{"prompt":"Notes: \"Cleaning: £___ per visit\". You hear: \"It’s normally thirty pounds a visit, but for regular customers it’s twenty-five.\" The caller is a new customer. What do you write?","options":["25","30","55"],"correct":1,"why":{"en":"Twenty-five is for regular customers. A new customer pays the normal price, 30.","tr":"Yirmi beş sürekli müşteriler için. Yeni bir müşteri normal fiyatı öder: 30.","fa":"بیست‌وپنج برای مشتری‌های همیشگی است. مشتری تازه قیمت عادی را می‌دهد: ۳۰."}},"remember":{"en":"Match each price to the words next to the gap, write what applies to this caller, and spell names letter by letter.","tr":"Her fiyatı boşluğun yanındaki kelimelerle eşleştir, bu arayan için geçerli olanı yaz ve isimleri harf harf yaz.","fa":"هر قیمت را با کلمه‌های کنار جای خالی جور کن، چیزی را بنویس که برای این تماس‌گیرنده صدق می‌کند و اسم‌ها را حرف به حرف بنویس."},"type":"explain","id":"c-x07-l1-e","course":"ielts-exams","exam":"exam-07","unit":"x07-l1"},"drill":{"type":"drill","skill":"listening","part":"Listening Part 1","title":{"en":"Homestart Hire","tr":"Homestart Hire","fa":"کرایه‌ی وسایل هوم‌استارت"},"timed":8,"ctx":["L1-home"],"script":[{"who":"Agent","line":"Good afternoon, Homestart Hire. Lucy speaking. How can I help you?"},{"who":"Tenant","line":"Hi. I've just moved into a rented flat, and the kitchen is completely empty. I was hoping to hire a fridge-freezer and a washing machine for a while."},{"who":"Agent","line":"No problem at all. Let's start with the fridge-freezer. We've got a tall model that's very popular with people in flats."},{"who":"Tenant","line":"How much is that?"},{"who":"Agent","line":"On a rolling monthly contract it's sixteen pounds a month. But if you sign up for twelve months, it comes down to fourteen."},{"who":"Tenant","line":"I'll be here for at least a year, so twelve months is fine."},{"who":"Agent","line":"Great. And what colour would you like? We normally have white or silver... oh, actually, I'm sorry, the system says we've run out of white until next month. It's silver only at the moment."},{"who":"Tenant","line":"Silver's fine. It doesn't really matter."},{"who":"Tenant","line":"Do you hire out microwaves as well? The flat doesn't have one."},{"who":"Agent","line":"We used to, but so few people asked for them that we stopped last year. Most people find it cheaper just to buy one."},{"who":"Agent","line":"Now, the washing machine. How wide is the space you've got for it?"},{"who":"Tenant","line":"About sixty centimetres, I measured it this morning."},{"who":"Agent","line":"Perfect, that's our standard size. The price, eleven pounds a month, includes installation, so our driver will connect it for you. We don't take away old machines, though, if there's one already there."},{"who":"Tenant","line":"There isn't. Does it have different programmes? I don't have many clothes to wash, so I don't want it running for two hours every time."},{"who":"Agent","line":"It has a quick programme. That's very useful for small loads. It takes about thirty minutes."},{"who":"Tenant","line":"That's exactly what I need. When could you deliver?"},{"who":"Agent","line":"Let me look. Wednesday is fully booked, I'm afraid. The next morning slot is Thursday, between eight and twelve."},{"who":"Tenant","line":"Thursday morning is fine. I'm working from home that day."},{"who":"Agent","line":"Delivery is usually forty pounds per item, but if we bring two items at the same time, it's twenty-five pounds altogether."},{"who":"Tenant","line":"Good. That makes sense. Will the driver need to come inside?"},{"who":"Agent","line":"Yes, they'll carry everything into the kitchen and check that both machines are working before they leave. Just make sure there's a clear path through the flat."},{"who":"Agent","line":"Now some other information. We offer insurance for three pounds a month. It covers all repairs and any accidental damage, so if you drop something on the glass shelf, for example, we'll replace it."},{"who":"Tenant","line":"I'll take that. What's the minimum length of contract?"},{"who":"Agent","line":"For the monthly option it's six months. You've chosen twelve, so that doesn't apply to you, but it's useful to know if you ever want to change."},{"who":"Tenant","line":"OK."},{"who":"Agent","line":"Can I take your name for the account?"},{"who":"Tenant","line":"Yes. It's Tom Delahunt."},{"who":"Agent","line":"Could you spell your surname for me?"},{"who":"Tenant","line":"Sure. D-E-L-A-H-U-N-T."},{"who":"Agent","line":"Thank you. And when the driver arrives, you'll need to show some identification. A lot of people show a utility bill, but that isn't enough for us, I'm afraid. We need to see your passport."},{"who":"Tenant","line":"That's fine. I'll have it ready."},{"who":"Agent","line":"Lovely. I'll send you a confirmation by email this afternoon."},{"who":"Tenant","line":"Thanks very much. And will the payments come out automatically?"},{"who":"Agent","line":"Yes, on the first day of each month. You'll get a reminder by text a few days before, so there are no surprises."},{"who":"Tenant","line":"Perfect. Thanks for your help."}],"notes":{"title":"Homestart Hire: order for a new flat","lines":["Fridge-freezer","Cost on a 12-month contract: £(1) ___ a month","Colour: (2) ___","Washing machine","Price includes (3) ___","Has a (4) ___ programme for small loads","Delivery","On (5) ___ morning","Charge for both items: £(6) ___","Other information","Insurance covers repairs and accidental (7) ___","Minimum contract for the monthly option: (8) ___ months","Name on the account: Tom (9) ___","On the delivery day, show the driver your (10) ___"]},"groups":[{"instruction":"Questions 1-10. Complete the notes below. Write ONE WORD AND/OR A NUMBER for each answer.","qtype":"note","questions":[{"n":1,"kind":"gap","prompt":"Fridge-freezer · cost on a 12-month contract: £___ a month","accept":["14","fourteen"],"limit":1,"evidence":"it comes down to fourteen","why":{"en":"£16 is the rolling monthly price. With twelve months \"it comes down to fourteen\".","tr":"16 £ aylık yenilenen fiyat. On iki ayla \"on dörde düşüyor\".","fa":"۱۶ پوند قیمت ماهانه‌ی بدون تعهد است. با قرارداد دوازده‌ماهه «به چهارده کم می‌شود»."},"trap":["TR-price"]},{"n":2,"kind":"gap","prompt":"Fridge-freezer · colour: ___","accept":["silver"],"limit":1,"evidence":"It's silver only at the moment","why":{"en":"White has run out until next month: \"It’s silver only at the moment.\"","tr":"Beyaz gelecek aya kadar tükenmiş: \"Şu an yalnızca gümüş rengi var.\"","fa":"سفید تا ماه بعد تمام شده: «فعلاً فقط نقره‌ای داریم»."},"trap":["TR-selfcorrect"]},{"n":3,"kind":"gap","prompt":"Washing machine · price includes ___","accept":["installation"],"limit":1,"evidence":"includes installation","why":{"en":"\"The price... includes installation.\" Taking away an old machine is not included.","tr":"\"Fiyata... kurulum dahil.\" Eski makinenin götürülmesi dahil değil.","fa":"«قیمت... شامل نصب است». بردن ماشین قدیمی شامل نیست."},"trap":["TR-paraphrase"]},{"n":4,"kind":"gap","prompt":"Washing machine · has a ___ programme for small loads","accept":["quick"],"limit":1,"evidence":"It has a quick programme","why":{"en":"\"It has a quick programme. That’s very useful for small loads.\" \"programme\" is printed.","tr":"\"Hızlı bir programı var. Küçük yükler için çok kullanışlı.\" \"programme\" yazılı.","fa":"«یک برنامه‌ی سریع دارد. برای بارهای کم خیلی به درد می‌خورد». «programme» چاپ شده."},"trap":["TR-printed"]},{"n":5,"kind":"gap","prompt":"Delivery · on ___ morning","accept":["Thursday"],"limit":1,"evidence":"The next morning slot is Thursday","why":{"en":"Wednesday is fully booked. \"The next morning slot is Thursday.\"","tr":"Çarşamba tamamen dolu. \"Bir sonraki sabah saati perşembe.\"","fa":"چهارشنبه کاملاً پر است. «وقتِ صبحِ بعدی پنجشنبه است»."},"trap":["TR-selfcorrect"]},{"n":6,"kind":"gap","prompt":"Delivery · charge for both items: £___","accept":["25","twenty-five"],"limit":1,"evidence":"it's twenty-five pounds altogether","why":{"en":"£40 is per item; for two items at once \"it’s twenty-five pounds altogether\".","tr":"40 £ ürün başına; iki ürün aynı anda gelirse \"toplam yirmi beş pound\".","fa":"۴۰ پوند برای هر وسیله است؛ برای دو وسیله با هم «روی‌هم بیست‌وپنج پوند»."},"trap":["TR-price"]},{"n":7,"kind":"gap","prompt":"Insurance · covers repairs and accidental ___","accept":["damage"],"limit":1,"evidence":"any accidental damage","why":{"en":"\"It covers all repairs and any accidental damage.\" \"accidental\" is printed.","tr":"\"Tüm onarımları ve her türlü kazara hasarı kapsar.\" \"accidental\" yazılı.","fa":"«همه‌ی تعمیرها و هر خسارت تصادفی را پوشش می‌دهد». «accidental» چاپ شده."},"trap":["TR-printed"]},{"n":8,"kind":"gap","prompt":"Contract · minimum for the monthly option: ___ months","accept":["6","six"],"limit":1,"evidence":"For the monthly option it's six months","why":{"en":"\"For the monthly option it’s six months.\" Twelve is what the caller chose.","tr":"\"Aylık seçenek için altı ay.\" On iki, arayanın seçtiği süre.","fa":"«برای گزینه‌ی ماهانه شش ماه است». دوازده مدتی است که تماس‌گیرنده انتخاب کرد."},"trap":["TR-paraphrase"]},{"n":9,"kind":"gap","prompt":"Name on the account: Tom ___","accept":["Delahunt"],"limit":1,"evidence":"D-E-L-A-H-U-N-T","why":{"en":"Spelled D-E-L-A-H-U-N-T. Every letter must be right.","tr":"D-E-L-A-H-U-N-T diye harf harf. Her harf doğru olmalı.","fa":"حرف به حرف: D-E-L-A-H-U-N-T. همه‌ی حرف‌ها باید درست باشند."},"trap":["TR-spell"]},{"n":10,"kind":"gap","prompt":"On the delivery day · show the driver your ___","accept":["passport"],"limit":1,"evidence":"We need to see your passport","why":{"en":"A utility bill \"isn’t enough\". \"We need to see your passport.\"","tr":"Fatura \"yeterli değil\". \"Pasaportunuzu görmemiz gerekiyor.\"","fa":"قبض آب و برق «کافی نیست». «باید گذرنامه‌ات را ببینیم»."},"trap":["TR-paraphrase"]}]}],"audio":{"voices":{"Announcer":{"accent":"British (standard Southern)","gender":"M","tts":{"engine":"kokoro","voice":"bm_george"},"role":"Recorded rubric"},"Agent":{"accent":"British (Southern English)","gender":"F","tts":{"engine":"kokoro","voice":"bf_isabella"},"role":"Hire company assistant"},"Tenant":{"accent":"North American","gender":"M","tts":{"engine":"kokoro","voice":"am_adam"},"role":"Tenant who phones the company"}},"sequence":[{"type":"announcer","text":"Part 1. You will hear a telephone conversation between a man who has moved into a rented flat and a woman who works for a hire company. First, you have some time to look at Questions 1 to 6."},{"type":"pause","seconds":30,"note":"reading time, Questions 1-6"},{"type":"announcer","text":"Now listen carefully and answer Questions 1 to 6."},{"type":"lines","from":0,"to":18,"note":"phone line: light telephone filter on both voices"},{"type":"announcer","text":"Before you hear the rest of the conversation, you have some time to look at Questions 7 to 10."},{"type":"pause","seconds":30,"note":"reading time, Questions 7-10"},{"type":"announcer","text":"Now listen and answer Questions 7 to 10."},{"type":"lines","from":19,"to":34},{"type":"announcer","text":"That is the end of Part 1. You now have half a minute to check your answers.","after":30}]},"id":"c-x07-l1-d","course":"ielts-exams","exam":"exam-07","unit":"x07-l1"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"I’m afraid Monday is fully booked.\" This means...","options":["there are no free times on Monday","Monday is the best day","Monday costs more"],"correct":0,"why":{"en":"Fully booked = every slot is taken.","tr":"Fully booked = bütün saatler dolu.","fa":"fully booked یعنی همه‌ی وقت‌ها پر شده."}},{"tests":"paraphrase","point":1,"prompt":"Notes: \"Price includes delivery\". Which words in a recording mean the same?","options":["delivery is extra","you can collect it yourself","delivery is free with this price"],"correct":2,"why":{"en":"If the price includes delivery, there is nothing extra to pay for it.","tr":"Fiyata teslimat dahilse onun için fazladan ödeme yoktur.","fa":"اگر قیمت شامل تحویل است، پول جداگانه‌ای برایش نمی‌دهی."}},{"tests":"method","point":2,"prompt":"Gap: \"Rent: £___ a month on a two-year contract\". You hear \"£90 a month, or £80 if you sign for two years\". What do you write?","options":["90","80","170"],"correct":1,"why":{"en":"The words next to the gap, \"on a two-year contract\", choose the second price.","tr":"Boşluğun yanındaki \"on a two-year contract\" ikinci fiyatı seçtiriyor.","fa":"کلمه‌های کنار جای خالی، «on a two-year contract»، قیمت دوم را انتخاب می‌کنند."}},{"tests":"trap","point":3,"prompt":"Gap: \"Bring a ___ as proof of address\". You hear: \"Most people bring a bank statement, but we only accept a council tax bill.\" What do you write?","options":["council tax bill","bank statement","statement"],"correct":0,"why":{"en":"What most people bring is not accepted. Only the council tax bill is.","tr":"Çoğu insanın getirdiği kabul edilmiyor. Yalnızca belediye vergisi faturası kabul ediliyor.","fa":"چیزی که بیشتر آدم‌ها می‌آورند پذیرفته نیست. فقط قبض عوارض شهرداری پذیرفته می‌شود."}},{"tests":"trap","point":2,"prompt":"Gap: \"Colour: ___\". You hear: \"It usually comes in black, but that’s sold out, so you can have red or green.\" The caller says \"Green, please.\" What do you write?","options":["black","red","green"],"correct":2,"why":{"en":"Black is sold out; the caller chooses green.","tr":"Siyah tükenmiş; arayan yeşili seçiyor.","fa":"مشکی تمام شده؛ تماس‌گیرنده سبز را انتخاب می‌کند."}}],"id":"c-x07-l1-x","course":"ielts-exams","exam":"exam-07","unit":"x07-l1"}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
